<?php $post=$post??[];$resourcePath=$resourcePath??'/admin/posts';$entityLabel=$entityLabel??'noticia'; ?><form class="editor-form" method="post" enctype="multipart/form-data" action="<?= $post && !empty($post['id'])?url($resourcePath.'/'.$post['id']):url($resourcePath) ?>"><?= csrf_field() ?><?php if($error):?><div class="form-error full"><?= e($error) ?></div><?php endif;?><section class="form-main admin-panel"><h2>Contenido del <?= e($entityLabel) ?></h2><label>Título *<input name="title" required maxlength="180" value="<?= e($post['title']??'') ?>" placeholder="Escribe un título claro e informativo"></label><label>URL amigable<input name="slug" value="<?= e($post['slug']??'') ?>" placeholder="se-genera-desde-el-titulo"></label><label>Bajada o resumen<textarea name="excerpt" rows="3" maxlength="350" placeholder="Resumen que aparecerá en las tarjetas"><?= e($post['excerpt']??'') ?></textarea></label><label>Contenido *</label><div class="rich-editor" data-rich-editor><div class="rich-toolbar" role="toolbar" aria-label="Formato de texto"><button type="button" data-command="bold"><b>N</b></button><button type="button" data-command="italic"><i>K</i></button><button type="button" data-command="underline"><u>S</u></button><button type="button" data-command="formatBlock" data-value="h2">Título</button><button type="button" data-command="insertUnorderedList">• Lista</button><button type="button" data-command="createLink">Enlace</button><button type="button" data-command="removeFormat">Limpiar</button></div><div class="rich-canvas" contenteditable="true"><?= $post['body']??'' ?></div><textarea class="rich-source" name="body" required hidden><?= e($post['body']??'') ?></textarea></div></section><aside><section class="admin-panel"><h2>Publicación</h2><label>Estado<select name="status"><option value="draft" <?= ($post['status']??'')==='draft'?'selected':'' ?>>Borrador</option><option value="published" <?= ($post['status']??'published')==='published'?'selected':'' ?>>Publicada</option></select></label><label>Fecha y hora<input type="datetime-local" name="published_at" value="<?= e(isset($post['published_at'])?date('Y-m-d\TH:i',strtotime($post['published_at'])):date('Y-m-d\TH:i')) ?>"></label><label class="check"><input type="checkbox" name="featured" value="1" <?= !empty($post['featured'])?'checked':'' ?>> Destacar en portada</label><button class="primary-button">Guardar noticia →</button></section><section class="admin-panel"><h2>Clasificación</h2><label>Categoría<select name="category_id" required><?php foreach($categories as $category):?><option value="<?= $category['id'] ?>" <?= (int)($post['category_id']??0)===(int)$category['id']?'selected':'' ?>><?= !empty($category['parent_name']) ? e($category['parent_name']).' — ' : '' ?><?= e($category['name']) ?></option><?php endforeach;?></select></label><label>Etiquetas<input name="tags" value="<?= e($post['tags']??'') ?>" placeholder="municipio, costa, invierno"></label><span class="hint">Sepáralas con comas.</span></section><section class="admin-panel"><h2>Imagen principal obligatoria</h2><label>Subir imagen<input type="file" name="upload" accept="image/jpeg,image/png,image/webp"></label><span class="hint">JPG, PNG o WebP. Máximo 5 MB.</span><label>o importar desde una URL<input type="url" name="image" value="<?= e($post['image']??'') ?>" placeholder="https://..."></label><span class="hint">La imagen externa se copiará al servidor para que no desaparezca cuando el enlace original caduque.</span></section></aside></form>
